{
  "findings": [
    {
      "check_id": "CKV_AZURE_35",
      "title": "Ensure default network access rule for Storage Accounts is set to deny",
      "resource": "azurerm_storage_account_network_rules.notification_storage_rules",
      "severity": "MEDIUM",
      "explanation": "The default network access rule for the Storage Account is set to 'Allow', potentially exposing it to unauthorized access from the internet."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account_network_rules\" \"notification_storage_rules\" {\n  storage_account_id = azurerm_storage_account.notification_storage.id\n  default_action     = \"Deny\"\n  ip_rules           = [\"127.0.0.1\"]\n  bypass             = [\"Metrics\", \"Logging\"]\n}",
  "fix_summary": "Changed the default_action from 'Allow' to 'Deny' to restrict access to the Storage Account by default."
}
